FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 068: rolled walls between flat walls unfolded and refolded, a shelled box recognized with rips. Generated by tools/fixtures/gen-batch-068.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function pointAtFraction(context is Context, part is Query, fx is number, fy is number, fz is number) returns Vector
{
    const b = evBox3d(context, { "topology" : part, "tight" : true });
    return vector(b.minCorner[0] + fx * (b.maxCorner[0] - b.minCorner[0]),
                  b.minCorner[1] + fy * (b.maxCorner[1] - b.minCorner[1]),
                  b.minCorner[2] + fz * (b.maxCorner[2] - b.minCorner[2]));
}

function atFraction(context is Context, part is Query, entityType is EntityType, fx is number, fy is number, fz is number) returns Query
{
    return qContainsPoint(qOwnedByBody(part, entityType), pointAtFraction(context, part, fx, fy, fz));
}

function bodyCounts(context is Context) returns map
{
    const all = qEverything(EntityType.BODY);
    return { "solids" : evaluateQueryCount(context, qBodyType(all, BodyType.SOLID)),
             "active" : evaluateQueryCount(context, qActiveSheetMetalFilter(all, ActiveSheetMetal.YES)) };
}

// The part's faces' areas and kinds, to compare.
function faceAreas(context is Context, part is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(part, EntityType.FACE)))
    {
        const s = evSurfaceDefinition(context, { "face" : face, "returnBSplinesAsOther" : true });
        out = append(out, { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6), "type" : s.surfaceType });
    }
    return out;
}

// sheet-metal-unfold: a rolled wall between two flat walls, unfolded holding the first flat wall
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(-30, 0) * millimeter, "end" : vector(0, 0) * millimeter });
    skArc(s1, "a1", { "start" : vector(0, 0) * millimeter, "mid" : vector(14.142136, 5.857864) * millimeter, "end" : vector(20, 20) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(20, 20) * millimeter, "end" : vector(20, 40) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.EXTRUDE, "sketchCurves" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "bendArcs" : qNothing(), "endBound" : SMExtrudeBoundingType.BLIND, "oppositeExtrudeDirection" : false, "depth" : 25 * millimeter, "symmetric" : false, "hasSecondDirection" : false });
    sheetMetalUnfold(context, id + "unfold1", { "unfoldAll" : false, "partToUnfold" : qNothing(), "entitiesToUnfold" : qNthElement(qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CYLINDER), 0), "holdEntity" : qClosestTo(qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.PLANE), vector(-15, 0, 12.5) * millimeter) });
    return { "counts" : bodyCounts(context), "faces" : faceAreas(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID)) };
}

