// sheet-metal-recognize: a 40 x 30 x 20 block shelled 2 mm from its top, recognized with 1 mm bends
export function c003(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    shell(context, id + "shell1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 20) * millimeter), "thickness" : 2 * millimeter });
    sheetMetalRecognize(context, id + "recognize1", { "bodies" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "radius" : 1 * millimeter, "changeThickness" : false, "keepInputParts" : false, "kFactor" : 0.45, "minimalClearance" : 0.02 * millimeter });
    return { "counts" : bodyCounts(context), "faces" : faceAreas(context, qBodyType(qEverything(EntityType.BODY), BodyType.SOLID)) };
}
